BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE tenant(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE organisation(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenant(id),legal_name text NOT NULL,legal_form text NOT NULL,jurisdiction text NOT NULL DEFAULT 'UK',version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id));
CREATE TABLE engagement(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenant(id),organisation_id uuid NOT NULL REFERENCES organisation(id),period_start date NOT NULL,period_end date NOT NULL,framework text NOT NULL,sector_profile text,status text NOT NULL DEFAULT 'DRAFT',version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),CHECK(period_end>=period_start));
CREATE INDEX engagement_tenant_org_idx ON engagement(tenant_id,organisation_id);
CREATE TABLE import_snapshot(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenant(id),engagement_id uuid NOT NULL REFERENCES engagement(id),sequence_no integer NOT NULL,content_hash text NOT NULL,storage_key text NOT NULL,record_count integer NOT NULL,debit_total numeric(30,2) NOT NULL,credit_total numeric(30,2) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(engagement_id,sequence_no));
CREATE TABLE source_account(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenant(id),organisation_id uuid NOT NULL REFERENCES organisation(id),external_id text,account_code text NOT NULL,account_name text NOT NULL,UNIQUE(organisation_id,account_code));
CREATE TABLE canonical_account(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),taxonomy_version text NOT NULL,canonical_code text NOT NULL,name text NOT NULL,report_line text NOT NULL,normal_balance text NOT NULL CHECK(normal_balance IN ('DEBIT','CREDIT')),UNIQUE(taxonomy_version,canonical_code));
CREATE TABLE account_mapping(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenant(id),engagement_id uuid REFERENCES engagement(id),source_account_id uuid NOT NULL REFERENCES source_account(id),canonical_account_id uuid NOT NULL REFERENCES canonical_account(id),mapping_source text NOT NULL,status text NOT NULL DEFAULT 'CONFIRMED',version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE trial_balance(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenant(id),engagement_id uuid NOT NULL REFERENCES engagement(id),state text NOT NULL CHECK(state IN ('SOURCE','IMPORTED','ADJUSTED','FINAL','FILED')),version_no integer NOT NULL,source_import_snapshot_id uuid REFERENCES import_snapshot(id),content_hash text NOT NULL,generated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(engagement_id,state,version_no));
CREATE TABLE trial_balance_line(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),trial_balance_id uuid NOT NULL REFERENCES trial_balance(id),tenant_id uuid NOT NULL REFERENCES tenant(id),source_account_id uuid NOT NULL REFERENCES source_account(id),canonical_account_id uuid REFERENCES canonical_account(id),dimensions jsonb NOT NULL DEFAULT '{}'::jsonb,debit numeric(30,2) NOT NULL DEFAULT 0,credit numeric(30,2) NOT NULL DEFAULT 0,CHECK(debit>=0 AND credit>=0));
CREATE TABLE audit_event(event_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),occurred_at_utc timestamptz NOT NULL,recorded_at_utc timestamptz NOT NULL DEFAULT now(),tenant_id uuid NOT NULL REFERENCES tenant(id),organisation_id uuid,engagement_id uuid,actor_type text NOT NULL,actor_id text NOT NULL,event_type text NOT NULL,object_type text NOT NULL,object_id text NOT NULL,version_before integer,version_after integer,previous_hash text,new_hash text,reason text,correlation_id text NOT NULL,causation_id text,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,event_hash text NOT NULL,ledger_integrity_reference text);
CREATE INDEX audit_event_engagement_time_idx ON audit_event(tenant_id,engagement_id,occurred_at_utc,event_id);
CREATE RULE audit_event_no_update AS ON UPDATE TO audit_event DO INSTEAD NOTHING;
CREATE RULE audit_event_no_delete AS ON DELETE TO audit_event DO INSTEAD NOTHING;
COMMIT;
